111|      `SELECT e.*, n.label AS to_label, n.type AS to_type, n.file_path AS to_file, n.start_line AS to_line
112|       FROM edges e JOIN nodes n ON n.id = e.to_id
113|       WHERE e.from_id = $sid AND e.relation = 'OVERRIDDEN_BY'
