2|
3|function placeholders(values, prefix) {
4|  return {
5|    sql: values.map((_, index) => `$${prefix}${index}`).join(','),
6|    params: Object.fromEntries(values.map((value, index) => [`${prefix}${index}`, value])),
7|  };
8|}
9|
10|// `withCallerSets` is opt-in and only `graph_callers` passes it: its refusal is the one whose
11|// subject IS the caller set, so a dead-end list of names is the milestone's named failure there and
12|// merely noise in graph_impact or graph_trace.
13|export function expandClassRollupTargets(db, symbol, { withCallerSets = false } = {}) {
14|  // resolveSymbol handles class-qualified forms (C++ `Class::method`,
15|  // dotted `Class.method`) by falling back to the bare name and
16|  // disambiguating via extra.qname when the parent is named. Critical
17|  // for C++ where agents naturally ask `GpuSimFramework::setGravAxis`.
18|  const targets = resolveSymbol(db, symbol);
19|  const ambiguity = buildAmbiguousMatchMessage(symbol, targets, 5, null,
20|    { callerSetsFrom: withCallerSets ? db : null });
21|  if (ambiguity) {
22|    return {
23|      targets: [],
24|      targetIds: [],
25|      rolledUp: false,
26|      header: '',
27|      methodIds: [],
28|      error: ambiguity,
29|    };
30|  }
31|  if (targets.length === 0) {
32|    return { targets: [], targetIds: [], rolledUp: false, header: '', methodIds: [], error: '' };
33|  }
34|
35|  const classTargets = targets.filter((target) => target.type === 'Class');
36|  if (classTargets.length === 0) {
37|    return {
38|      targets,
39|      targetIds: targets.map((target) => target.id),
40|      rolledUp: false,
41|      header: '',
42|      methodIds: [],
43|      error: '',
44|    };
45|  }
46|
47|  const classIds = classTargets.map((target) => target.id);
48|  const { sql, params } = placeholders(classIds, 'class');
49|  const methods = db.all(
50|    `SELECT DISTINCT n.id
51|     FROM edges e
52|     JOIN nodes n ON n.id = e.to_id
53|     WHERE e.relation = 'CONTAINS'
54|       AND e.from_id IN (${sql})
55|       AND n.type = 'Method'`,
56|    params,
57|  );
58|
59|  const methodIds = methods.map((row) => row.id);
60|  const targetIds = [...new Set([...classIds, ...methodIds])];
61|  const methodCount = methodIds.length;
62|  const classCount = classTargets.length;
63|  const label = classCount === 1 ? 'Class' : 'Classes';
64|  const header = `ROLLUP ${label} "${symbol}" across ${methodCount} method${methodCount === 1 ? '' : 's'}`;
65|
66|  return { targets, targetIds, rolledUp: true, header, methodIds, error: '' };
67|}
68|
69|export function collapseCallerEdges(edges, rolledUpSymbol) {
70|  const grouped = new Map();
71|
72|  for (const edge of edges) {
73|    const key = `${edge.from_id}:${edge.depth ?? 1}`;
74|    const existing = grouped.get(key);
75|    if (!existing) {
76|      grouped.set(key, {
77|        ...edge,
78|        fan_in: 1,
79|        to_label: rolledUpSymbol ?? edge.to_label,
80|      });
81|      continue;
82|    }
83|
84|    existing.fan_in += 1;
85|    if ((edge.confidence ?? 0) > (existing.confidence ?? 0)) {
86|      existing.confidence = edge.confidence;
87|      existing.source_file = edge.source_file;
88|      existing.source_line = edge.source_line;
89|    }
90|  }
91|
92|  return [...grouped.values()];
