2|// stores. Audit (echoes/borrow sweep, codegraph 0171785): on Windows an agent
3|// naturally passes `src\foo.cpp`, but every File node's file_path is stored with
4|// forward slashes — so a backslash path arg silently matched nothing and verbs
5|// returned an empty/"not found" result (a trust regression on our own OS).
6|//
7|// Scope this to PATH args only (file=, path=, a path-shaped query) — never to a
8|// symbol name, which legitimately never contains a backslash anyway.
9|export function normalizePathArg(value) {
10|  if (typeof value !== 'string' || !value) return value;
11|  return value.replace(/\\/g, '/');
